def max_Product(arr):
    # Handle edge case: Array with fewer than 2 elements
    if len(arr) < 2:
        return None

    # Initialize variables to track the two largest and two smallest elements
    max1 = max2 = float('-inf')  # Two largest numbers
    min1 = min2 = float('inf')   # Two smallest numbers

    # Traverse the array to find the two largest and two smallest numbers
    for num in arr:
        # Update the two largest numbers
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the two smallest numbers
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # Compute the products of the two pairs
    product_positive = max1 * max2  # Product of two largest numbers
    product_negative = min1 * min2  # Product of two smallest numbers

    # Return the pair with the higher product
    if product_positive >= product_negative:
        return (max1, max2)
    else:
        return (min1, min2)

# Example usage and tests
assert max_Product([1, 2, 3, 4, 7, 0, 8, 4]) == (8, 7)
assert max_Product([-10, -20, 1, 2, 3]) == (-10, -20)
assert max_Product([5]) == None
assert max_Product([-1, -2]) == (-1, -2)
